ingredient_name = #{ingredientName}, major_category_name = #{majorCategoryName}, sub_category_name = #{subCategoryName}, storage_type = #{storageType}, order_unit = #{orderUnit}, capacity = #{capacity}, capacity_unit = #{capacityUnit}, management_method = #{managementMethod}, consumption_period = #{consumptionPeriod}, summer_consumption_period = #{summerConsumptionPeriod}, expiration_period = #{expirationPeriod}, supply_price = #{supplyPrice}, supply_quantity = #{supplyQuantity},
